    $shouldReplace = [];

    foreach ($replace as $key => $value) {
        if ($value instanceof Closure) {
            $line = preg_replace_callback(
                '/<'.$key.'>(.*?)<\/'.$key.'>/',
                fn ($args) => $value($args[1]),
